; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; VIEW: the map window and map access (259E-298E).
;
; The screen layout and the map window. Text cells are 8 x 8 pixels (40 x 25); the map window
; is cells 1-22 of rows 1-22 (11 x 11 tiles of 16 x 16 pixels), the message window rows
; 11h-17h, columns 18h-27h. Entry points:
;   BuildView      fill the 11 x 11 view buffer (ViewTiles = the start-up code at 24C4) around
;                  the party, hide what forests, mountains and walls block, draw it
;   PrintMsg       print a string in the message window (ScrollMsg scrolls it a line)
;   DrawFrame          clear the screen and draw the frame lines
;   ClearView      blank the map window
;   MapCellAddr    the address and byte of a map cell (x, y); DungeonCell the same in a dungeon
;   ShowGemMap, ShowDungeonMap   the "Peer at gem" maps
; BuildView also leaves the shapes of the party's cell and its four neighbours in the bytes
; TileEast, TileWest, TileNorth, TileSouth and TileHere (WORLD), which the
; movement and Enter commands read.

CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN CursorCol:BYTE
EXTRN CursorRow:BYTE
EXTRN ScreenSeg:BYTE
EXTRN SwapCursor:NEAR
EXTRN PutChar:NEAR
EXTRN DrawChar:NEAR
EXTRN FillCell:NEAR
EXTRN ClearScreen:NEAR
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN DrawView:NEAR
EXTRN MapBuf:BYTE
EXTRN DungeonMap:BYTE
EXTRN ScreenRowTbl:BYTE
EXTRN PartyTile:BYTE
EXTRN Location:BYTE
EXTRN PlayerXY:BYTE
EXTRN DungeonLevel:BYTE
EXTRN MapWraps:BYTE
EXTRN StartUp:NEAR
EXTRN ViewCell31:NEAR
EXTRN ViewCell3B:NEAR
EXTRN ViewCell45:NEAR
EXTRN TileEast:BYTE
EXTRN TileWest:BYTE
EXTRN TileNorth:BYTE
EXTRN TileSouth:BYTE
EXTRN TileHere:BYTE
PUBLIC ShowGemMap
PUBLIC PrintMsg
PUBLIC ScrollMsg
PUBLIC DrawFrame
PUBLIC BuildView
PUBLIC ClearView
PUBLIC MapCellAddr
PUBLIC DungeonCell
PUBLIC ShowDungeonMap
;------------------------------------------------------------------------------
; ShowGemMap: the "Peer at gem" map of a town or the surface: the whole
; 64 x 64 map, 2 x 2 pixels a cell, from pixel (20h) in the map window, a pattern by
; shape (water black, grass/brush/forest cyan dots, the rest white), then the party's four
; pixels flash until a key is pressed (the key is eaten). Called by the P command (LOOP).
; In: nothing. Uses: nothing (saves all).
;------------------------------------------------------------------------------
ShowGemMap:	pushf	;@259E
	push ax	;@259F
	push bx	;@25A0
	push cx	;@25A1
	push dx	;@25A2
	push es	;@25A3
	mov es, word ptr ScreenSeg	;@25A4
	call ClearView	; the pixels are XORed: start from black	;@25A8
	mov cx, 0	; CL = x, CH = y	;@25AB
GemMap_Cell:	mov bx, cx	;@25AE
	call MapCellAddr	; AL = the map byte at (CL, CH)	;@25B0
	cmp al, 0	; water: left black	;@25B3
	je GemMap_Next	;@25B5
	mov ah, 40h	; colour 1 (cyan) in the pixel mask	;@25B7
	cmp al, 4	; grass	;@25B9
	je GemMap_Grass	;@25BB
	cmp al, 8	; brush	;@25BD
	je GemMap_Brush	;@25BF
	cmp al, 0Ch	; forest	;@25C1
	je GemMap_Forest	;@25C3
	mov ah, 0C0h	; colour 3 (white)	;@25C5
	cmp al, 10h	; mountains	;@25C7
	je GemMap_Solid	;@25C9
	cmp al, 20h	; floor	;@25CB
	je GemMap_Floor	;@25CD
	cmp al, 8Ch	; wall	;@25CF
	je GemMap_Solid	;@25D1
	jmp GemMap_Other	;@25D3
GemMap_Grass:	mov dh, cl	; grass: one pixel, right column, top or bottom by x parity	;@25D6
	and dh, 1	;@25D8
	mov dl, 1	;@25DB
	call XorGemPixel	;@25DD
	jmp short GemMap_Next	;@25E0
GemMap_Brush:	mov dx, 101h	; brush: the lower right pixel	;@25E2
	call XorGemPixel	;@25E5
	jmp short GemMap_Next	;@25E8
GemMap_Forest:	mov dx, 1	; forest: the right column (then the brush pixel)	;@25EA
	call XorGemPixel	;@25ED
	jmp GemMap_Brush	;@25F0
GemMap_Floor:	mov dx, 0	; floor: the left column	;@25F2
	call XorGemPixel	;@25F5
	mov dx, 100h	;@25F8
	call XorGemPixel	;@25FB
	jmp short GemMap_Next	;@25FE
GemMap_Solid:	mov dx, 0	; solid: the left column, then the forest's right column	;@2600
	call XorGemPixel	;@2603
	mov dx, 100h	;@2606
	call XorGemPixel	;@2609
	jmp GemMap_Forest	;@260C
GemMap_Other:	mov dx, 0	; anything else (towns, creatures, ...): the top row	;@260E
	call XorGemPixel	;@2611
	mov dx, 1	;@2614
	call XorGemPixel	;@2617
GemMap_Next:	inc cl	;@261A
	and cl, 3Fh	;@261C
	je GemMap_NextRow	;@261F
	jmp GemMap_Cell	;@2621
GemMap_NextRow:	inc ch	;@2623
	cmp ch, 40h	;@2625
	jae GemMap_Party	;@2628
	jmp GemMap_Cell	;@262A
GemMap_Party:	mov cx, word ptr PlayerXY	;@262C
	mov bl, byte ptr Location	; saved	;@2630
	mov byte ptr Location, 1	; 1: KeyReady skips the idle animation (Location = 1)	;@2634
	mov ah, 0C0h	;@2639
GemMap_Blink:	mov dx, 0	; flash the party's four pixels in turn	;@263B
	call XorGemPixel	;@263E
	call KeyReady	;@2641
	jne GemMap_Key	;@2644
	mov dx, 101h	;@2646
	call XorGemPixel	;@2649
	call KeyReady	;@264C
	jne GemMap_Key	;@264F
	mov dx, 1	;@2651
	call XorGemPixel	;@2654
	call KeyReady	;@2657
	jne GemMap_Key	;@265A
	mov dx, 100h	;@265C
	call XorGemPixel	;@265F
	call KeyReady	;@2662
	je GemMap_Blink	;@2665
GemMap_Key:	call ReadKey	; eat the key	;@2667
	mov byte ptr Location, bl	;@266A
	pop es	;@266E
	pop dx	;@266F
	pop cx	;@2670
	pop bx	;@2671
	pop ax	;@2672
	popf	;@2673
	ret	;@2674
;------------------------------------------------------------------------------
; XorGemPixel: XOR a pixel of the gem map: map cell (CL = x, CH = y), sub-pixel DL (x) and DH
; (y) of its 2 x 2; screen pixel (2*CL + DL + 20h, 2*CH + DH + 20h). AH = the colour in the
; top pixel position (40h cyan, 0C0h white); ES = the screen. Uses: nothing (saves all).
;------------------------------------------------------------------------------
XorGemPixel:	push ax	;@2675
	push bx	;@2676
	push cx	;@2677
	shl cl, 1	;@2678
	shl ch, 1	;@267A
	add cl, dl	;@267C
	add ch, dh	;@267E
	add ch, 20h	;@2680
	add cl, 20h	;@2683
	mov al, cl	; byte column = pixel x / 4	;@2686
	shr al, 1	;@2688
	shr al, 1	;@268A
	and cl, 3	; shift the colour to pixel x mod 4	;@268C
	shl cl, 1	;@268F
	shr ah, cl	;@2691
	mov bl, ch	;@2693
	mov bh, 0	;@2695
	shl bx, 1	;@2697
	mov bx, word ptr ScreenRowTbl[bx]	; BX = screen offset of the scan line	;@2699
	add bl, al	;@269D
	adc bh, 0	;@269F
	xor byte ptr es:[bx], ah	;@26A2
	pop cx	;@26A5
	pop bx	;@26A6
	pop ax	;@26A7
	ret	;@26A8
;------------------------------------------------------------------------------
; PrintMsg: print the NUL-ended string at SI in the message window (rows 11h-17h, columns
; 18h-27h). 0Ah = new line (scroll up and start at column 18h of row 17h); a character past
; column 27h wraps the same way. If the cursor is outside the window it starts on a new line.
; In: SI. Out: the cursor after the text. Uses: nothing (saves all).
;------------------------------------------------------------------------------
PrintMsg:	pushf	;@26A9
	push ax	;@26AA
	push dx	;@26AB
	push si	;@26AC
	cld	;@26AD
	mov dx, word ptr CursorCol	; DL = column, DH = row	;@26AE
	cmp dh, 11h	;@26B2
	jb PrintMsg_NewLine	;@26B5
	cmp dl, 18h	;@26B7
	jb PrintMsg_NewLine	;@26BA
PrintMsg_Next:	lodsb	;@26BC
	cmp al, 0	;@26BD
	je PrintMsg_Done	;@26BF
	cmp al, 0Ah	;@26C1
	je PrintMsg_NewLine	;@26C3
	cmp dl, 27h	; the last column: draw without moving the cursor	;@26C5
	je PrintMsg_LastCol	;@26C8
	ja PrintMsg_Wrap	;@26CA
PrintMsg_Put:	call PutChar	;@26CC
PrintMsg_Advance:	inc dl	;@26CF
	jmp PrintMsg_Next	;@26D1
PrintMsg_NewLine:	call ScrollMsg	;@26D3
	mov dl, 18h	;@26D6
	jmp PrintMsg_Next	;@26D8
PrintMsg_Done:	pop si	;@26DA
	pop dx	;@26DB
	pop ax	;@26DC
	popf	;@26DD
	ret	;@26DE
	db 0B6h,17h,0B2h,18h,0E8h,71h,28h,0EBh,0D4h	; dead: DX = 1718h, call SwapCursor, jmp _Next	;@26DF
PrintMsg_LastCol:	call DrawChar	; the cursor stays; DL passes 27h: the next char wraps	;@26E8
	jmp PrintMsg_Advance	;@26EB
PrintMsg_Wrap:	call ScrollMsg	;@26ED
	mov dl, 18h	;@26F0
	jmp PrintMsg_Put	;@26F2
;------------------------------------------------------------------------------
; ScrollMsg: scroll the message window (rows 11h-17h, columns 18h-27h) up a line and put the
; cursor at row 17h, column 18h. Uses: nothing (saves all).
;------------------------------------------------------------------------------
ScrollMsg:	push ax	;@26F4
	push bx	;@26F5
	push cx	;@26F6
	push dx	;@26F7
	push bp	;@26F8
	mov al, 1	; one line	;@26F9
	mov bh, 0	;@26FB
	mov ch, 11h	;@26FD
	mov cl, 18h	;@26FF
	mov dh, 17h	;@2701
	mov dl, 27h	;@2703
	mov ah, 6	; BIOS: scroll the window up	;@2705
	int 10h	;@2707
	mov dh, 17h	;@2709
	mov dl, 18h	;@270B
	call SwapCursor	; the cursor to row 17h, column 18h (the old position in DX is dropped)	;@270D
	pop bp	;@2710
	pop dx	;@2711
	pop cx	;@2712
	pop bx	;@2713
	pop ax	;@2714
	ret	;@2715
;------------------------------------------------------------------------------
; DrawFrame: clear the screen and draw the frame in pattern 2222h
; (magenta): the left edge, the column 23 divider, the top and bottom rows of the map window,
; the five lines across the right part (rows 0, 4, 8, 12, 16: around the four players' status
; areas) and the right edge down to row 16. A text cell row is 140h bytes in each CGA bank.
; Uses: nothing (saves all).
;------------------------------------------------------------------------------
DrawFrame:	pushf	;@2716
	push ax	;@2717
	push bx	;@2718
	push cx	;@2719
	mov ax, 0	;@271A
	call ClearScreen	; AX = 0: all black	;@271D
	mov ax, 2222h	;@2720
	mov bx, 0	; column 0, 24 rows	;@2723
	mov cx, 18h	;@2726
DrawFrame_Left:	call FillCell	;@2729
	add bx, 140h	;@272C
	loop DrawFrame_Left	;@2730
	mov bx, 2Eh	; column 23 (byte 2Eh)	;@2732
	mov cx, 18h	;@2735
DrawFrame_Divider:	call FillCell	;@2738
	add bx, 140h	;@273B
	loop DrawFrame_Divider	;@273F
	mov bx, 0	; row 0, columns 0-23	;@2741
	mov cx, 18h	;@2744
DrawFrame_Top:	call FillCell	;@2747
	add bx, 2	;@274A
	loop DrawFrame_Top	;@274D
	mov bx, 1CC0h	; row 23 (17h * 140h)	;@274F
	mov cx, 18h	;@2752
DrawFrame_Bottom:	call FillCell	;@2755
	add bx, 2	;@2758
	loop DrawFrame_Bottom	;@275B
	mov bx, 30h	; row 0, columns 24-39 (the 17th cell falls on the left edge: harmless)	;@275D
	mov cx, 11h	;@2760
DrawFrame_Line0:	call FillCell	;@2763
	add bx, 2	;@2766
	loop DrawFrame_Line0	;@2769
	mov bx, 530h	; row 4	;@276B
	mov cx, 11h	;@276E
DrawFrame_Line4:	call FillCell	;@2771
	add bx, 2	;@2774
	loop DrawFrame_Line4	;@2777
	mov bx, 0A30h	; row 8	;@2779
	mov cx, 11h	;@277C
DrawFrame_Line8:	call FillCell	;@277F
	add bx, 2	;@2782
	loop DrawFrame_Line8	;@2785
	mov bx, 0F30h	; row 12	;@2787
	mov cx, 11h	;@278A
DrawFrame_Line12:	call FillCell	;@278D
	add bx, 2	;@2790
	loop DrawFrame_Line12	;@2793
	mov bx, 1430h	; row 16	;@2795
	mov cx, 11h	;@2798
DrawFrame_Line16:	call FillCell	;@279B
	add bx, 2	;@279E
	loop DrawFrame_Line16	;@27A1
	mov bx, 4Eh	; column 39 (byte 4Eh), rows 0-16	;@27A3
	mov cx, 11h	;@27A6
DrawFrame_Right:	call FillCell	;@27A9
	add bx, 140h	;@27AC
	loop DrawFrame_Right	;@27B0
	pop cx	;@27B2
	pop bx	;@27B3
	pop ax	;@27B4
	popf	;@27B5
	ret	;@27B6
; SightStep, indexed by a view column or row (0-10): the step towards the centre (5).
; SightRowStep: the same step for a row, in view cells (11 a row).
SightStep label byte
	db 1h,1h,1h,1h,1h,0h,0FFh,0FFh,0FFh,0FFh,0FFh	;@27B7
SightRowStep label byte
	db 0Bh,0Bh,0Bh,0Bh,0Bh,0h,0F5h,0F5h,0F5h,0F5h,0F5h	;@27C2
;------------------------------------------------------------------------------
; BuildView: fill ViewTiles (the 121 shape numbers at 24C4, row by row) with the map around the
; party at PlayerXY (the party in the centre, cell 3Ch). On a map that wraps (MapWraps =
; MapWraps = 0FFh: Sosaria, Ambrosia) the coordinates wrap; in a town or castle a cell outside the
; map shows grass. Then: save the four neighbours and the party's own cell in TileEast-TileHere,
; put PartyTile in the centre, hide (shape 24h, void) every cell whose line to the centre
; passes a forest, mountain, wall or void, and draw the window (DrawView).
; Uses: nothing (saves all).
;------------------------------------------------------------------------------
BuildView:	pushf	;@27CD
	push ax	;@27CE
	push bx	;@27CF
	push cx	;@27D0
	push dx	;@27D1
	push di	;@27D2
	push bp	;@27D3
	cld	;@27D4
	mov dx, word ptr PlayerXY	;@27D5
	sub dh, 5	; DL = x, DH = y of the top left cell	;@27D9
	sub dl, 5	;@27DC
	lea di, StartUp	;@27DF
	mov cx, 0	; CH = view column, CL = view row	;@27E3
BuildView_Cell:	cmp byte ptr MapWraps, 0FFh	; MapWraps = MapWraps	;@27E6
	je BuildView_Wrap	;@27EB
	mov ah, ch	;@27ED
	add ah, dl	;@27EF
	cmp ah, 40h	;@27F1
	jae BuildView_Outside	;@27F4
	mov al, cl	;@27F6
	add al, dh	;@27F8
	cmp al, 40h	;@27FA
	jb BuildView_Read	;@27FC
BuildView_Outside:	mov al, 1	; outside a town: grass	;@27FE
	jmp short BuildView_Store	;@2800
BuildView_Wrap:	mov ah, dl	;@2802
	add ah, ch	;@2804
	and ah, 3Fh	;@2806
	mov al, dh	;@2809
	add al, cl	;@280B
	and al, 3Fh	;@280D
BuildView_Read:	mov bh, al	;@280F
	mov bl, 0	;@2811
	shr bx, 1	;@2813
	shr bx, 1	;@2815
	or bl, ah	;@2817
	mov al, byte ptr MapBuf[bx]	;@2819
	shr al, 1	; shape = byte / 4	;@281D
	shr al, 1	;@281F
BuildView_Store:	stosb	;@2821
	inc ch	;@2822
	cmp ch, 0Bh	;@2824
	jne BuildView_Cell	;@2827
	mov ch, 0	;@2829
	inc cl	;@282B
	cmp cl, 0Bh	;@282D
	jne BuildView_Cell	;@2830
	mov al, byte ptr ViewCell31	; cell 31h: north of the party	;@2832
	mov byte ptr TileNorth, al	;@2835
	mov al, byte ptr ViewCell45+2	; cell 47h: south	;@2838
	mov byte ptr TileSouth, al	;@283B
	mov al, byte ptr ViewCell3B+2	; cell 3Dh: east	;@283E
	mov byte ptr TileEast, al	;@2841
	mov al, byte ptr ViewCell3B	; cell 3Bh: west	;@2844
	mov byte ptr TileWest, al	;@2847
	mov al, byte ptr ViewCell3B+1	; cell 3Ch: the party's own cell	;@284A
	mov byte ptr TileHere, al	;@284D
	mov al, byte ptr PartyTile	;@2850
	mov byte ptr ViewCell3B+1, al	; the party in the centre	;@2853
	mov dh, 0Ah	; line of sight: from cell 78h (row 10, column 10) down to 0	;@2856
	mov dl, 0Ah	;@2858
	push dx	;@285A
	mov bp, sp	;@285B
	mov dh, 78h	; DH = the cell being tested	;@285D
	mov bh, 0	;@285F
BuildView_Sight:	mov cl, byte ptr [bp]	; CL = its column, CH = its row	;@2861
	mov ch, byte ptr [bp+1]	;@2864
	mov dl, dh	;@2867
BuildView_SightStep:	mov al, dl	; one step towards the centre	;@2869
	mov bl, cl	;@286B
	add al, byte ptr SightStep[bx]	;@286D
	mov bl, ch	;@2871
	add al, byte ptr SightRowStep[bx]	;@2873
	cmp al, 3Ch	; reached the centre: visible	;@2877
	je BuildView_SightNext	;@2879
	mov dl, al	;@287B
	mov bl, al	;@287D
	mov al, byte ptr StartUp[bx]	;@287F
	cmp al, 3	; forest	;@2883
	je BuildView_Hidden	;@2885
	cmp al, 4	; mountains	;@2887
	je BuildView_Hidden	;@2889
	cmp al, 23h	; wall	;@288B
	je BuildView_Hidden	;@288D
	cmp al, 24h	; void (also a cell already hidden)	;@288F
	je BuildView_Hidden	;@2891
	mov bl, cl	; move the column and row a step towards the centre	;@2893
	add cl, byte ptr SightStep[bx]	;@2895
	mov bl, ch	;@2899
	add ch, byte ptr SightStep[bx]	;@289B
	jmp BuildView_SightStep	;@289F
BuildView_Hidden:	mov bl, dh	;@28A1
	mov byte ptr StartUp[bx], 24h	; hidden: void	;@28A3
BuildView_SightNext:	dec dh	;@28A8
	dec byte ptr [bp]	;@28AA
	jns BuildView_Sight	;@28AD
	mov byte ptr [bp], 0Ah	;@28AF
	dec byte ptr [bp+1]	;@28B3
	jns BuildView_Sight	;@28B6
	add sp, 2	;@28B8
	call DrawView	;@28BB
	pop bp	;@28BE
	pop di	;@28BF
	pop dx	;@28C0
	pop cx	;@28C1
	pop bx	;@28C2
	pop ax	;@28C3
	popf	;@28C4
	ret	;@28C5
;------------------------------------------------------------------------------
; ClearView: blank the map window (rows 1-22, columns 1-22) with the BIOS scroll call.
; Uses: nothing (saves all).
;------------------------------------------------------------------------------
ClearView:	push ax	;@28C6
	push bx	;@28C7
	push cx	;@28C8
	push dx	;@28C9
	push bp	;@28CA
	mov bx, 0	;@28CB
	mov cx, 101h	;@28CE
	mov dx, 1616h	;@28D1
	mov ax, 600h	; BIOS scroll, AL = 0: clear the window	;@28D4
	int 10h	;@28D7
	pop bp	;@28D9
	pop dx	;@28DA
	pop cx	;@28DB
	pop bx	;@28DC
	pop ax	;@28DD
	ret	;@28DE
;------------------------------------------------------------------------------
; MapCellAddr: the map cell at x = BL, y = BH (0-63): BX = its address in MapBuf (y*64 + x),
; AL = its byte (the shape times 4). Uses: nothing else.
;------------------------------------------------------------------------------
MapCellAddr:	pushf	;@28DF
	mov al, bl	;@28E0
	mov bl, 0	;@28E2
	shr bx, 1	;@28E4
	shr bx, 1	;@28E6
	add bl, al	;@28E8
	lea bx, MapBuf[bx]	;@28EA
	mov al, byte ptr [bx]	;@28EE
	popf	;@28F0
	ret	;@28F1
;------------------------------------------------------------------------------
; DungeonCell: the dungeon cell at x = BL, y = BH (0-15) of level DungeonLevel: BX = its
; address in DungeonMap (level*256 + y*16 + x), AL = its byte. Uses: nothing else.
;------------------------------------------------------------------------------
DungeonCell:	pushf	;@28F2
	shl bh, 1	;@28F3
	shl bh, 1	;@28F5
	shl bh, 1	;@28F7
	shl bh, 1	;@28F9
	add bl, bh	;@28FB
	mov bh, byte ptr DungeonLevel	;@28FD
	lea bx, DungeonMap[bx]	;@2901
	mov al, byte ptr [bx]	;@2905
	popf	;@2907
	ret	;@2908
;------------------------------------------------------------------------------
; ShowDungeonMap: the "Peer at gem" map in a dungeon: the current level
; as characters (16 x 16 from row 4, column 4): cell C0h -> char 1, A0h -> 2, 80h (wall) -> 3,
; 30h -> 4, 20h -> 5, 10h -> 6 (the ladders), 0 (floor) -> char 0, any other '?'; then
; a '*' flashes at the party's position until a key (eaten). Called by the P command.
; Uses: nothing (saves all; the cursor is restored).
;------------------------------------------------------------------------------
ShowDungeonMap:	pushf	;@2909
	push ax	;@290A
	push bx	;@290B
	push cx	;@290C
	call ClearView	;@290D
	push word ptr CursorCol	;@2910
	mov cx, 0	;@2914
	mov word ptr CursorCol, 404h	; row 4, column 4	;@2917
DunMap_Cell:	mov bx, cx	;@291D
	call DungeonCell	;@291F
	cmp al, 0C0h	; C0h: the code is set before each je	;@2922
	mov ah, 1	;@2924
	je DunMap_Put	;@2926
	cmp al, 0A0h	;@2928
	mov ah, 2	;@292A
	je DunMap_Put	;@292C
	cmp al, 80h	;@292E
	mov ah, 3	;@2930
	je DunMap_Put	;@2932
	cmp al, 30h	; ladders up and down	;@2934
	mov ah, 4	;@2936
	je DunMap_Put	;@2938
	cmp al, 20h	; ladder down	;@293A
	mov ah, 5	;@293C
	je DunMap_Put	;@293E
	cmp al, 10h	; ladder up	;@2940
	mov ah, 6	;@2942
	je DunMap_Put	;@2944
	cmp al, 0	;@2946
	mov ah, al	;@2948
	je DunMap_Put	;@294A
	mov ah, 3Fh	; anything else: '?'	;@294C
DunMap_Put:	mov al, ah	;@294E
	call PutChar	;@2950
	inc cl	;@2953
	and cl, 0Fh	;@2955
	jne DunMap_Cell	;@2958
	inc ch	;@295A
	inc byte ptr CursorRow	;@295C
	mov byte ptr CursorCol, 4	;@2960
	cmp ch, 10h	;@2965
	jb DunMap_Cell	;@2968
	mov ax, word ptr PlayerXY	;@296A
	add ax, 404h	; the party's cell (x + 4, y + 4)	;@296D
	mov word ptr CursorCol, ax	;@2970
DunMap_Blink:	mov al, 2Ah	; '*' and blank in turn	;@2973
	call DrawChar	;@2975
	mov al, 20h	;@2978
	call DrawChar	;@297A
	call KeyReady	;@297D
	je DunMap_Blink	;@2980
	call ReadKey	;@2982
	pop word ptr CursorCol	;@2985
	pop cx	;@2989
	pop bx	;@298A
	pop ax	;@298B
	popf	;@298C
	ret	;@298D
CODE ENDS
END
